WITH long_format AS (SELECT id, device_code, metric_name, val FROM (SELECT id, device_code, temp_c, pressure, humidity FROM device_readings) src UNPIVOT (val FOR metric_name IN (temp_c AS TEMP_C_VAL, pressure AS PRESSURE, humidity AS HUMIDITY)) u) SELECT CASE WHEN val >= 65 THEN 'LARGE' ELSE 'SMALL' END AS val_tier, metric_name, COUNT_IF(device_code = 'DV-03') AS dv_03_events, COUNT(CASE WHEN device_code = 'DV-04' THEN 1 END) AS dv_04_count, AVG(val) FILTER (WHERE device_code = 'DV-03') AS dv_03_avg_val FROM long_format GROUP BY 1, 2
